SELECT id, external_userid, follow_userid, state, welcome_text_used, text_source,
       errcode, errmsg, skipped_reason, create_time
FROM crm_wecom_welcome_log


        AND external_userid = #{externalUserid}


        AND state = #{state}


        AND errcode = #{errcode}


        AND create_time >= #{params.beginTime}::timestamp


        AND create_time <= #{params.endTime}::timestamp


ORDER BY id DESC
